    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();

        if (N == 1) {
            sb.append("1\n");
        } else if (N == 2) {
            sb.append("-1\n");
        } else if (N % 2 == 1) {
            for (int i = 1; i <= N; i++) {
                for (int j = 1; j <= N; j++) {
                    if (j > 1) sb.append(' ');
                    sb.append((i - 1) * N + j);
                }
                sb.append('\n');
            }
        } else {
            int k = N - 1;
            int m = (k - 1) / 2;
            int[] S = new int[k];
            int idx = 0;
            S[idx++] = -(m + 2);
            for (int x = -m; x <= -2; x++) {
                S[idx++] = x;
            }
            for (int x = 1; x <= m + 1; x++) {
                S[idx++] = x;
            }

            int c = k + 3;
            int minS = -(m + 2);
            int M = 1 - (c + 1) * minS;

            int[][] mat = new int[N][N];
            for (int i = 0; i < k; i++) {
                for (int j = 0; j < k; j++) {
                    mat[i][j] = M + c * S[i] + S[j];
                }
                mat[i][k] = M + c * S[i];
            }
            for (int j = 0; j < k; j++) {
                mat[k][j] = M + S[j];
            }
            mat[k][k] = M;

            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (j > 0) sb.append(' ');
                    sb.append(mat[i][j]);
                }
                sb.append('\n');
            }
        }

        System.out.print(sb);
    }
}
